sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
   var field = 'approval';
   var visable_field = 'approval_visable';
   var cnMap = {
		'not requested': '待申请',
        'requested': '审批中',
        'Approved': '已通过',
        'Rejected': '已拒绝'

   };
    // 延迟300ms，等字段值加载完成
    setTimeout(function(){
        var stateValue = g_form.getValue(field);
        if(stateValue && cnMap[stateValue]){
            g_form.setValue(visable_field, cnMap[stateValue]);
        }
        // 隐藏原始英文审批字段
        g_form.setDisplay(field, false);
    }, 300);
}
